#include <array>
#include <cassert>
#include <iostream>
#include <stdexcept>
class Bindings {
    std::array<int,3> keys_{{1,2,3}}; // 점프, 공격, 회피. 키0은 미할당이며 여기서는 금지.
    static bool valid(const std::array<int,3>& v) {
        for(int k:v) if(k<1 || k>4) return false;
        return v[0]!=v[1] && v[0]!=v[2] && v[1]!=v[2];
    }
public:
    const std::array<int,3>& keys() const { return keys_; }
    void replace(const std::array<int,3>& proposed) {
        if(!valid(proposed)) throw std::invalid_argument("invalid bindings");
        keys_=proposed; // 전체 검증이 끝난 뒤 한 번에 반영한다.
    }
    void rebind(unsigned action,int key) {
        if(action>=3 || key<1 || key>4) throw std::invalid_argument("range");
        std::array<int,3> next=keys_;
        for(unsigned i=0;i<3;++i) if(i!=action && next[i]==key) next[i]=keys_[action];
        next[action]=key; // 충돌 정책: 기존 두 행동의 키 교환
        replace(next);
    }
};
#ifdef NDEBUG
#error "Tests require assertions enabled."
#endif
int main() {
    Bindings b;
    b.rebind(0,2); assert((b.keys()==std::array<int,3>{{2,1,3}}));
    b.rebind(0,2); assert((b.keys()==std::array<int,3>{{2,1,3}}));
    b.rebind(2,4); assert((b.keys()==std::array<int,3>{{2,1,4}}));
    const auto before=b.keys(); int rejected=0;
    try { b.rebind(3,1); } catch(const std::invalid_argument&) { ++rejected; }
    try { b.rebind(0,0); } catch(const std::invalid_argument&) { ++rejected; }
    try { b.replace({{1,1,2}}); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected==3 && b.keys()==before);
    for(unsigned n=0;n<10000;++n) {
        b.rebind(n%3,static_cast<int>(n%4)+1);
        const auto k=b.keys();
        assert(k[0]!=k[1] && k[0]!=k[2] && k[1]!=k[2]);
        for(int x:k) assert(x>=1 && x<=4);
    }
    std::cout<<"binding tests passed: 10000 rebindings\n";
}
